// Provider 2 games — Spine FX layer, shared by all ten (skeletons generated by
// provider2/build_fx.py into img/<game>/fx/). Pattern of js/baku-fx.js:
//
//   #fxBack (over the bg image, under the reels) — bg_desk / bg_mob, `idle`.
//   front = the game's symbol stage (#spineCanvas, over the reels): frame and
//           logo (`idle`, `win` while a win is on screen; the DOM logo hides
//           once the Spine one is up), burst (small win), shower (coin rain
//           over the money popups: the canvas is lifted above #screenDim via
//           body.fx-over-dim and the base instances are dimmed in Spine).
//
// Every instance is anchored to its DOM element, so CSS stays the only source
// of layout truth. If WebGL or an asset fails, P2Fx.ready stays false and the
// game keeps its static frame/logo.

(function () {
  let root = '';
  let back = null;
  let front = null;
  const res = {};
  let bgInst = null;
  let bgVariant = null;
  let frameInst = null;
  let logoInst = null;
  let burstInst = null;
  let burstTimer = null;
  let showerInst = null;
  let winOn = false;

  const P2Fx = { ready: false };

  function isMobile() {
    return window.matchMedia('(orientation: portrait)').matches;
  }

  function load(stage, name) {
    return SpineEngine.SpineResource.load(stage.assetManager, `${root}/${name}`, { premultipliedAlpha: true })
      .then((r) => { res[name] = r; return r; });
  }

  function make(name, anchorEl) {
    const inst = res[name].createInstance();
    const sd = res[name].skeletonData;
    inst.anchorEl = anchorEl;
    inst.fit = 1;
    inst.boundsOverride = { x: sd.x, y: sd.y, width: sd.width, height: sd.height };
    return inst;
  }

  // The engine fits 'contain' / 'width' / 'height'; the bg must cover the
  // screen like the <img> under it (object-fit: cover), so pick the axis.
  function coverBg() {
    if (!bgInst) return;
    const el = document.getElementById('screen');
    const sd = bgInst.resource.skeletonData;
    bgInst.fitMode = el.clientWidth / el.clientHeight > sd.width / sd.height ? 'width' : 'height';
  }

  function mountBg() {
    const v = isMobile() ? 'bg_mob' : 'bg_desk';
    if (v === bgVariant || !res[v]) return;
    if (bgInst) back.removeBase(bgInst);
    bgVariant = v;
    bgInst = make(v, document.getElementById('screen'));
    coverBg();
    bgInst.play('idle', true);
    back.addBase(bgInst);
  }

  P2Fx.load = function load_(opts) {
    root = opts.root;
    if (!window.spine || !window.SpineEngine) return Promise.resolve(false);
    try {
      back = new SpineEngine.SpineStage(document.getElementById('fxBack'));
      front = opts.frontStage || new SpineEngine.SpineStage(document.getElementById('fxFront'));
    } catch (err) {
      console.warn('[provider2-fx] no WebGL — static fallback', err);
      return Promise.resolve(false);
    }
    return Promise.all([
      load(back, isMobile() ? 'bg_mob' : 'bg_desk'),
      load(front, 'frame'),
      load(front, 'logo'),
      load(front, 'burst'),
      load(front, 'shower'),
    ]).then(() => {
      P2Fx.ready = true;
      mountBg();
      frameInst = make('frame', document.querySelector('.reel__frame'));
      frameInst.play('idle', true);
      front.addBaseBehindAll(frameInst);
      logoInst = make('logo', document.querySelector('.logo'));
      logoInst.play('idle', true);
      front.addBase(logoInst);
      document.body.classList.add('fx-ready');
      load(back, isMobile() ? 'bg_desk' : 'bg_mob').catch(() => {});
      window.addEventListener('resize', () => {
        const v = isMobile() ? 'bg_mob' : 'bg_desk';
        if (res[v]) mountBg();
        else load(back, v).then(mountBg).catch(() => {});
        coverBg();
      });
      return true;
    }).catch((err) => {
      console.warn('[provider2-fx] assets failed — static fallback', err);
      return false;
    });
  };

  P2Fx.setWin = function setWin(on) {
    if (!P2Fx.ready || on === winOn) return;
    winOn = on;
    const clip = on ? 'win' : 'idle';
    frameInst.play(clip, true);
    logoInst.play(clip, true);
  };

  // Small win: star burst + coin fountain out of the reel window, once.
  P2Fx.burst = function burst() {
    if (!P2Fx.ready) return;
    if (burstInst) front.removeOverlay(burstInst);
    clearTimeout(burstTimer);
    const inst = make('burst', document.getElementById('reelGrid'));
    inst.play('win', false);
    front.addOverlay(inst);
    burstInst = inst;
    // timer, not the complete event: a hidden tab ticks no frames
    burstTimer = setTimeout(() => {
      front.removeOverlay(inst);
      if (burstInst === inst) burstInst = null;
    }, 1700);
  };

  P2Fx.startShower = function startShower() {
    if (!P2Fx.ready) return;
    P2Fx.stopShower();
    const screen = document.getElementById('screen');
    const inst = make('shower', screen);
    const wide = screen.clientWidth >= screen.clientHeight;
    inst.fitMode = wide ? 'width' : 'height';
    if (!wide) inst.fit = 0.55;
    inst.play('start', false);
    inst.queue('rain', true);
    showerInst = inst;
    front.addOverlay(inst);
    front.setBaseDim(true);
    document.body.classList.add('fx-over-dim');
  };

  P2Fx.stopShower = function stopShower() {
    if (!showerInst) return;
    front.removeOverlay(showerInst);
    showerInst = null;
    front.setBaseDim(false);
    document.body.classList.remove('fx-over-dim');
  };

  window.P2Fx = P2Fx;
})();
